    case "$1" in
        aj)
            remote https://raw.githubusercontent.com/biko-73/AjPanel/main/installer.sh ;;
        subs)
            remote https://raw.githubusercontent.com/popking159/SubsSupportPro/refs/heads/main/myinstaller.sh ;;
        transmission)
